def cargar(apps, schema_editor):
    Indicador = apps.get_model("core", "Indicador")
    for ind in Indicador.objects.all():
        pob, ven, fue, sd = CONTRATO.get(ind.rol, CONTRATO["tecnico"])
        if ind.tipo == "manual":
            fue = "Carga manual mensual (Carga de datos → Indicadores)"
        texto = ind.descripcion.split(". ")[0].rstrip(".")
        if "÷" in texto:
            num, den = [t.strip() for t in texto.split("÷", 1)]
        else:
            num, den = texto, ""
        Indicador.objects.filter(pk=ind.pk).update(
            poblacion=ind.poblacion or pob, ventana=ind.ventana or ven, fuente=ind.fuente or fue,
            sin_dato=ind.sin_dato or sd, numerador=ind.numerador or num[:250], denominador=ind.denominador or den[:250])



